Let $G$ be a graph
	and
	$P\neq \parr $ be a prime graph with $|V_{P}|=n$, and $M_1,\dots, M_n$ be non-empty graphs.
	If $\mathord{\vdash_{\mathsf{GS}}\,}{G\parr P\llparenthesis M_1, \dots, M_n\rrparenthesis}$, then one of the following holds:


	\begin{enumerate}[(A)]
		\item
		either there is a context $C[\cdot]_{R}$ 
		and graphs $K_1$, \dots, $K_n$, 
		such that  
		there are derivations
		\begin{equation*}
                  \scalebox{.92}{$
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
			\;,\;
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_i\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
			\quad\mbox{and}\quad
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
                        $}
			\hskip-1em
		\end{equation*}
		for all $i\in\{1,\ldots,n\}$,


		\item
		or there is a context $C[\cdot]_{R}$ and graphs $K_X$ and $K_Y$,
		such that 
		there are derivations
		\begin{equation*}
                  \scalebox{.92}{$
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
			\;,\;
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_X\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
			\;,\;
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_Y\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
			\quad\mbox{and}\quad
			\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
                        $}
			\hskip-1em
		\end{equation*}
		for some $i\in\{1,\ldots,n\}$.

	\end{enumerate}

Let $G$, $A$ and $B$ be graphs.
	If $\mathord{\vdash_{\mathsf{GS}}\,}{G\parr (A\otimes B)}$ then there is a context $C$ and there are graphs $K_A$ and $K_B$ 
	such that 
	there are derivations
	\begin{equation*}
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\;,\;		
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_A\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\;,\;
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_B\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\quad\mbox{and}\quad		
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\rlap{\quad.}
	\end{equation*}

Let $G$ be a graph,  and $A_1,\dots, A_n$ be non-empty graphs.

	If $\mathord{\vdash_{\mathsf{GS}}\,}{G\parr ({A_1\otimes \cdots \otimes A_n})}$, 
	then there is a context $C[\cdot]_{R}$ and graphs $K_1$, \dots , $K_n$, 
	such that  
	there are derivations
	\begin{equation*}
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\;,\;
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_i\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\quad\mbox{and}\quad
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\hskip-1em
	\end{equation*}
	for all $i\in\{1,\ldots,n\}$.

Let $G$ be a graph.
	If\/ $\mathord{\vdash_{\mathsf{GS}}\,}{G\parr a}$~ for an atom $a$, then there is a context $C[\cdot]_{R}$ such that 
 there are derivations
	\begin{equation*}
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\quad\mbox{and}\quad
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\rlap{\quad.}
	\end{equation*}

Let $A$ be a graph and $G[\cdot]_{S}$ be a context, such that\/
	$\mathord{\vdash_{\mathsf{GS}}\,}{G[A]_{S}}$. Then there are a
	context $C[\cdot]_{R}$ and a graph $K$, such that there are derivations
	\begin{equation*}
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_G\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\quad\mbox{and}\quad
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_A\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
		\quad\mbox{and}\quad
		\bgroup \mathrm{odsetframes} \mathrm{vlprepstructures}\mathrm{vlderivationinitaux}\mathcal{D}_C\vcenter{\copy\derboxone}\mathrm{vlderivationterm}
	\end{equation*}
	for any graph ${\mathcal X}$.
